css:
:root {
  --bg-base: #0a0a0a;
  --bg-surface: #111111;
  --bg-card: #1f1f1f;
  --border: #2a2a2a;
  --text: #fafafa;
  --text-muted: #a1a1aa;
  --accent: #0ea5e9;
  --success: #22c55e;
  --danger: #ef4444;
  --warning: #f59e0b;

  /* Uma cor por fonte de receita — a mesma em pílula, gráfico e avatar. */
  --src-empresa: #0ea5e9;
  --src-impressionart: #8b5cf6;
  --src-moto: #f59e0b;
  --src-mos: #22c55e;
  --src-nata: #ec4899;

  --fonte: 'Manrope', sans-serif;
  --fonte-titulo: 'Sora', sans-serif;
  --fonte-mono: 'JetBrains Mono', monospace;
}

body { background: var(--bg-base); color: var(--text); font-family: var(--fonte); }

/* Número em tabela, card ou badge nunca "dança" ao atualizar. */
.bs-num { font-variant-numeric: tabular-nums; }

.bs-badges {
  width: min(560px, 100%);
  display: flex; flex-wrap: wrap; gap: 8px;
  padding: 20px; border: 1px solid var(--border); border-radius: 12px; background: var(--bg-surface);
}

.bs-badge {
  padding: 4px 10px; border-radius: 6px;
  font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.04em;
  /* A cor cheia no texto, a mesma cor a 15% no fundo. Badge saturado sobre
     #0a0a0a rouba a atenção do número, que é o que importa na tela. */
  color: var(--cor);
  background: color-mix(in srgb, var(--cor) 15%, transparent);
}

.bs-b-ok { --cor: var(--success); }
.bs-b-esp { --cor: var(--warning); }
.bs-b-erro { --cor: var(--danger); }
.bs-b-mov { --cor: var(--accent); }
.bs-b-rev { --cor: var(--src-impressionart); }
.bs-b-neutro { --cor: var(--text-muted); }
